check('neutral full-stack manifest tracks validation quickfix eventflow and gamification', all(x in support for x in ['IntegrationArtifactKind.VALIDATIONS','IntegrationArtifactKind.ACTIONS','IntegrationArtifactKind.EVENT_FLOWS','IntegrationArtifactKind.GAMIFICATION_DEFINITIONS','textual-full-stack.json']))
