check('BESSER Web generates TypeScript full-stack textual bridge', 'hydra-textual-full-stack.ts' in b_web and 'typescriptFullStackBridgeSource' in b_web and 'fullStackNeutralFiles' in b_web)
check('BESSER Web plain package never references absent textual module', 'indexSource(boolean textual, boolean visual)' in b_web and "textual ? \"export * from './hydra-textual-full-stack.js';\"" in b_web)
